import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../build/host.gen.ts';

const deliverTo = async (h: any, to: string, action: string) => {
  const m = (await h.inFlight()).find((x: any) => x.to === to && x.action === action);
  assert.ok(m, `no ${action} to ${to}`);
  await h.deliver(m.id);
  return m;
};

test('initial state and unknown clients', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c9'), null);
  assert.equal((await h.acquire('c9')).ok, false);
  assert.equal((await h.expire()).ok, false);
  assert.equal((await h.release('c0')).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.acquire('c0')).ok, false);
  const [m] = await h.inFlight();
  assert.deepEqual({ from: m.from, to: m.to, action: m.action, data: m.data }, { from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  const [w] = await h.inFlight();
  assert.deepEqual(w.data, { from: 'c0', token: 1 });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 1 });
  assert.equal((await h.client('c0'))!.writing, false);
  assert.deepEqual(await h.release('c0'), { ok: true });
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
  assert.equal((await h.client('c0'))!.status, 'idle');
});

test('denied while held, and after two grants', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.equal((await h.client('c1'))!.status, 'idle');
  await h.release('c0'); await h.deliverAll();
  await h.acquire('c1'); await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1'); await h.deliverAll();
  await h.acquire('c0'); await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('expire, stale write refused', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  await h.write('c0');
  assert.deepEqual(await h.expire(), { ok: true });
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 0 });
  await deliverTo(h, 'lease', 'Write');
  const r = (await h.inFlight()).map((m: any) => m.action).sort();
  assert.deepEqual(r, ['Revoked', 'WriteRefused']);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.equal((await h.lease()).writes, 0);
});

test('revoked before granted', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await deliverTo(h, 'lease', 'Acquire');
  await h.expire();
  const rv = await deliverTo(h, 'c0', 'Revoked');
  assert.deepEqual(rv.data, { token: 1 });
  assert.equal((await h.client('c0'))!.status, 'requesting');
  await deliverTo(h, 'c0', 'Granted');
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 1, writing: false });
  assert.equal((await h.lease()).holder, null);
});

test('at most two writes', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  for (const expect of [1, 2, 2]) {
    assert.deepEqual(await h.write('c0'), { ok: true });
    await h.deliverAll();
    assert.equal((await h.lease()).writes, expect);
  }
});

