test('release is acknowledged', async () => {
  const h = await createHost();
  await h.acquire('c0'); await h.deliverAll();
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.equal((await h.client('c0'))!.status, 'releasing');
  assert.equal((await h.acquire('c0')).ok, false);
  await h.expire(); // the release has not arrived; the service still holds c0
  await deliverTo(h, 'c0', 'Revoked');
  assert.equal((await h.client('c0'))!.status, 'releasing');
  const rel = await deliverTo(h, 'lease', 'Release');
  assert.deepEqual(rel.data, { from: 'c0', token: 1 });
  const ack = await deliverTo(h, 'c0', 'Released');
